ssize_t device_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    ssize_t bytes_written = 0;
    struct device_info *dev_info = filp->private_data;
    struct element_info *element = NULL;

    if (!dev_info || !dev_info->active) {
        return -ENODEV;
    }

    if (count > MAX_WRITE_SIZE) {
        count = MAX_WRITE_SIZE;
    }

    element = kmalloc(sizeof(*element), GFP_KERNEL);
    if (!element) {
        return -ENOMEM;
    }

    element->data = kmalloc(count, GFP_KERNEL);
    if (!element->data) {
        kfree(element);
        return -ENOMEM;
    }

    if (copy_from_user(element->data, buf, count)) {
        kfree(element->data);
        kfree(element);
        return -EFAULT;
    }

    element->length = count;
    element->sequence = atomic_inc_return(&dev_info->sequence_number);

    spin_lock(&dev_info->lock);
    list_add_tail(&element->list, &dev_info->write_queue);
    spin_unlock(&dev_info->lock);

    wake_up_process(dev_info->worker_task);

    bytes_written = count;

    return bytes_written;
}

ssize_t dev_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    if (count > MAX_ALLOWED_SIZE)
        return -EINVAL;

    struct dev_lock *dev_lock = get_active_device_lock();
    if (!dev_lock)
        return -ENODEV;

    struct dev_info *dev_info = NULL;
    int err = 0;
    ssize_t bytes_written = 0;

    dev_info = kzalloc(sizeof(*dev_info), GFP_KERNEL);
    if (!dev_info) {
        err = -ENOMEM;
        goto out;
    }

    if (!is_device_connected(dev_lock)) {
        err = -ENODEV;
        goto out_free;
    }

    if (copy_from_user(dev_info->data, buf, count)) {
        err = -EFAULT;
        goto out_free;
    }

    update_sequence_number(dev_info);
    queue_element_for_processing(dev_info);

    bytes_written = count;
    *fpos += count;

out_free:
    kfree(dev_info);
out:
    release_device_reference(dev_lock);
    return (err < 0) ? err : bytes_written;
}

ssize_t device_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    if (count > MAX_ALLOWED_SIZE) {
        return -EINVAL;
    }

    struct device_data *dev_data = filp->private_data;
    struct mutex *lock = &dev_data->lock;
    struct element_info *elem;
    ssize_t bytes_written = 0;
    int ret = 0;

    mutex_lock(lock);

    if (!dev_data->device_connected) {
        mutex_unlock(lock);
        return -ENODEV;
    }

    elem = kzalloc(sizeof(*elem), GFP_KERNEL);
    if (!elem) {
        mutex_unlock(lock);
        return -ENOMEM;
    }

    elem->data = kmalloc(count, GFP_KERNEL);
    if (!elem->data) {
        kfree(elem);
        mutex_unlock(lock);
        return -ENOMEM;
    }

    if (copy_from_user(elem->data, buf, count)) {
        kfree(elem->data);
        kfree(elem);
        mutex_unlock(lock);
        return -EFAULT;
    }

    elem->length = count;
    elem->sequence_number = dev_data->next_seq_num++;
    list_add_tail(&elem->list, &dev_data->queue);

    bytes_written = count;
    dev_data->pending_bytes += count;

    mutex_unlock(lock);

    wake_up_process(dev_data->processing_thread);

    return bytes_written;
}

ssize_t dev_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    ssize_t ret = -EFAULT;

    if (count > MAX_ALLOWED_SIZE)
        return -EINVAL;

    struct dev_lock *lock = get_dev_lock();
    if (!lock)
        return -ENODEV;

    lock_acquire(lock);
    struct dev_info *dev = get_active_device();
    if (!dev || !dev->connected) {
        lock_release(lock);
        return -ENODEV;
    }

    struct elem_info *elem = alloc_elem_info();
    if (!elem) {
        lock_release(lock);
        return -ENOMEM;
    }

    if (copy_from_user(elem->data, buf, count)) {
        release_elem_info(elem);
        lock_release(lock);
        return -EFAULT;
    }

    elem->seq_num = get_next_seq_num();
    elem->len = count;

    queue_elem(dev, elem);

    ret = count;
    lock_release(lock);
    release_dev_lock(lock);
    put_dev(dev);
    return ret;
}

ssize_t dev_write(struct file *filp, const char __user *buf, size_t count, loff_t *fpos) {
    int ret;
    struct dev_info *dev;
    struct element_info *einfo;

    if (count > MAX_ALLOWED_SIZE)
        return -EINVAL;

    dev = get_active_dev();
    if (!dev)
        return -ENODEV;

    einfo = kmalloc(sizeof(struct element_info), GFP_KERNEL);
    if (!einfo) {
        put_dev(dev);
        return -ENOMEM;
    }

    ret = -EFAULT;
    if (copy_from_user(einfo->data, buf, count))
        goto out;

    einfo->seq_num = atomic_inc_return(&dev->seq_counter);
    einfo->length = count;

    spin_lock(&dev->lock);
    list_add_tail(&einfo->list, &dev->queue);
    spin_unlock(&dev->lock);

    wake_up_process(dev->worker_task);

    *fpos += count;
    ret = count;

out:
    kfree(einfo);
    put_dev(dev);
    return ret;
}
